1	export type Cell = [x: number, y: number];
2	
3	const isNeighbor = ([x, y]: Cell, [otherX, otherY]: Cell): boolean => {
4	  const isSameCell = x === otherX && y === otherY;
5	  const isWithinOneStep = Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
6	  return !isSameCell && isWithinOneStep;
7	};
8	
9	const countLivingNeighbors = (cell: Cell, livingCells: Cell[]): number =>
10	  livingCells.filter((other) => isNeighbor(cell, other)).length;
11	
12	export const nextGeneration = (livingCells: Cell[]): Cell[] =>
13	  livingCells.filter((cell) => countLivingNeighbors(cell, livingCells) === 3);
